"""Report physical scope, matched speed comparisons, and where complex repair loses."""
from statistics import median
from analyze import D,read,save,sha,from_two

def fmt(v,n=2):return f"{v:.{n}f}".replace(".",",")
def interval(x):return fmt(x[0],3)+" … "+fmt(x[1],3)
def main():
    v=read(D/"results.json");build=read(D/"build.json");lines=[]
    paired=read(D/"paired-commits.json.gz");w=read(D/"paired-commits.json")
    assert w["file"]==sha(D/"paired-commits.json.gz")
    prows=[(z[1],z[2],z[7]) for z in paired]
    durable={other:from_two(prows,"repair",other) for other in ("cost_certificate","rebuild")}
    save(D/"durability-paired-summary.json",{"matched":durable,"file":w["file"],"wal":w["wal"],"n_questions":192,"repeats":3})
    lines+=["# Обновление кешированной выдачи графовой памяти","",
        "Как быстро исправить выдачу из памяти, если при прежнем запросе изменился приоритет одного блока? На 192 вопросах кеш прежней выдачи позволил пропускать повторное чтение большинства источников. При этом простой контроль остатка токенов оказался столь же быстрым, как более сложный алгоритм с проверкой перекрытия интервалов и восстановлением суффикса.","",
        "Взяты 192 различные реальные тестовые траектории ISETrace, по одному вопросу на историю. Всего 122 596 допустимых блоков. Основной порядок и вероятности рассчитаны поверх R-GCN без content.next, альтернативные баллы получены поверх обычного R-GCN; модель fine_train и первые два защищённых PU фиксированы. Имитируются расписания появления и переоценки элементов. Все 192 выдачи при 2 048 в исходном состоянии в точности воспроизвели порядок предыдущего эксперимента.","",
        "## Что происходит при обновлении","",
        "В каждой материальной записи сохраняются выбранные идентификаторы, позиции, токенная стоимость и символьные интервалы. Когда меняется балл, проверяем, был ли элемент выбран раньше, и сколько места осталось до его новой позиции. Элемент, который не помещается, сохраняет прежнюю последовательность. Дополнительная проверка может доказать такой же результат по перекрытию интервалов. Если проверка не проходит, прежние решения строго до первой изменённой позиции сохраняются, а индекс пересчитывает оставшийся суффикс. Доказательство переносится на пакет изменений посредством индукции по полному порядку. При замене свыше 32 оценок реализация обращается к полному индексному проходу. Изменение защищённого ядра, токенной цены или геометрии потребует отдельной инвалидизации.","",
        "## Первичный результат на 2 048 токенах","",
        "| Обновление и сравнение C++17 | Кеш с суффиксом, мкс | Контроль, мкс | Отношение медиан | 95% парный ДИ |","|---|---:|---:|---:|---:|"]
    names={"random1":"Случайный балл","selected1":"Балл выбранного блока","random8":"8 случайных баллов","random32":"32 случайных балла","all":"Все различающиеся баллы"}
    controls={"rebuild":"индексная пересборка","cost_certificate":"только остаток токенов","interval_certificate":"остаток и перекрытие"}
    for case,other in [(x,"rebuild") for x in names]+[("random1","cost_certificate"),("random1","interval_certificate")]:
        row=v["native"][f"{case}/{other}"]
        lines.append(f"| {names[case]}, {controls[other]} | {fmt(row['candidate_us'])} | {fmt(row['baseline_us'])} | {fmt(row['ratio'],3)} | {interval(row['ratio_ci'])} |")
    lines+=["","У случайной правки упорядоченные блоки изменились в 19 из 192 вопросов; содержимое обслуживающей записи, включая обновлённый балл, изменилось в 24. В 168 случаях полный метод доказал пригодность прежней выдачи. За один проход прочитано 7 490 индексных строк, у полной пересборки — 90 823, у проверки только остатка — 8 880. Каждый метод читает индивидуальный кеш или записывает его по своим правилам. Строка SQL-результата и физическое чтение страницы различаются. На тех же 192 вопросах полная проверка выполнила 125 138 инструкций SQLite VM, простая проверка — 101 519, перестройка — 922 965. Это объясняет, почему меньшее число строк не обеспечило преимущества перед простой проверкой.",
       "","Изменение специально выбранного блока поменяло выдачу в 130/192 случаях. При 32 правках выбор менялся в 154/192, при полном обновлении — в 192/192. На восьми правках отношение медиан и медиана парной разности отражают разные свойства распределения. В нативном измерении разность на типичной паре составила всего −0,90 мкс; одного отношения медиан недостаточно для характеристики этого режима.","",
       "## Первичное измерение Python и SQLite","",
       "| Бюджет | Кеш, мкс | Полная индексная пересборка, мкс | Отношение медиан | 95% ДИ | Изменилось выдач из 192 |","|---:|---:|---:|---:|---:|---:|"]
    for b in (1024,1536,2048,3072):
        row=v["dynamic"][f"{b}/random1"];fx=v["branches"][f"{b}/random1"]
        lines.append(f"| {b:,} | {fmt(row['candidate_us'],1)} | {fmt(row['baseline_us'],1)} | {fmt(row['ratio'],3)} | {interval(row['ratio_ci'])} | {fx['changed_ids']} |".replace(",024"," 024").replace(",536"," 536").replace(",048"," 048").replace(",072"," 072"))
    row=v["dynamic"]["2048/insert1"]
    lines+=["",f"При появлении ранее скрытого реального блока и прежних баллах остальных Python-кеш занял {fmt(row['candidate_us'],1)} против {fmt(row['baseline_us'],1)} мкс, отношение {fmt(row['ratio'],3)} [{interval(row['ratio_ci'])}]. Порядок ответа изменился в 21/192 случаях.","",
        "## Стоимость чтения, хранения и записи","",
        "| Статическое чтение на 2 048 | Одно тёплое соединение, мкс | Новое соединение SQLite, мкс |","|---|---:|---:|"]
    for k,name in (("scan_sort","Поиск по вопросу и нативная сортировка SQLite"),("priority","Поток по покрывающему B-tree"),("materialized","Готовый материализованный ответ")):
        lines.append(f"| {name} | {fmt(v['static']['2048/warm'][k]['us'],1)} | {fmt(v['static']['2048/sqlite-cold'][k]['us'],1)} |")
    lines+=["","Закрытие соединения освобождало приватный кеш страниц SQLite. Файловый кеш Windows сохранялся. Время открытия соединения исключено. При первой фактической записи после повторного открытия кеш с проверкой и полная пересборка заняли 271,25 и 517,25 мкс, при тёплом соединении — 156,85 и 360,10 мкс.","",
        "Основная таблица заняла 3 817 472 байта, уникальный индекс вопроса и блока — 1 806 336. Построение дополнительного покрывающего индекса заняло 69,4 мс и 3 919 872 байта. Материализация 768 ответов на четыре бюджета в JSON заняла 2 433 024 байта. Построение с дополнительной независимой проверкой всех ответов заняло 461 мс. Для нативного испытания на одном бюджете бинарный кеш занял 561 152 байта, включая страницы SQLite. Все эти расходы возникают сверх получения p/c-баллов.","",
        "Отдельная серия выполнила 1 728 реальных транзакций с WAL и synchronous=FULL. Для каждого вопроса случайно перемешивался порядок трёх политик на отдельных идентично инициализированных копиях. Медианы с учётом COMMIT и доверительный интервал вычислены после трёх повторов.","",
        "| Контроль при долговременной записи | Кеш с суффиксом, мкс | Контроль, мкс | Отношение медиан | 95% ДИ |","|---|---:|---:|---:|---:|"]
    for k,label in (("rebuild","Полная пересборка"),("cost_certificate","Только проверка остатка")):
        row=durable[k];lines.append(f"| {label} | {fmt(row['candidate_us'],1)} | {fmt(row['baseline_us'],1)} | {fmt(row['ratio'],3)} | {interval(row['ratio_ci'])} |")
    lines+=["","При одинаковом порядке вопросов каждая из трёх политик записала одинаковое число байтов WAL. Между повторностями оно составляло от 2 760 432 до 2 785 152 байт. В отдельном измерении 192 записей без материализованной выдачи журнал занял 791 072 байта при обновлении только исходной таблицы и 2 529 712 байт с дополнительным покрывающим индексом. Хранение индекса и ответы ускоряют последующие чтения ценой дополнительной записи.","",
        "## Границы результата","",
        "Для этого распределения разреженных изменений сложная поддержка суффикса не даёт самостоятельного выигрыша времени относительно простой проверки остатка. Зато измерено, какую часть стоимости вызывает полная инвалидизация и где она предпочтительна. Опыт относится к повторно читаемым вопросам с уже вычисленными баллами и фиксированным защищённым ядром. Он измеряет синтетическое расписание правок на реальных данных, исключает вычисление новых embedding и признаков, инференс генератора и ответы агента. Полученные микросекунды относятся к локальной SQLite 3.50.4 под Windows с параллельной исследовательской нагрузкой.","",
        "Нативные повторы проверили 30 720 полных порядков. 4 608 отдельных изменённых состояний, 768 исходных состояний и 768 дополнительных пограничных примеров проверены полным независимым жадным проходом. Все совпадения точные. Время C++ измеряется внутри вызова между началом мутации и готовностью кеша, до отката экспериментальной фикстуры. Долговременные транзакции измерены отдельной серией. Кластер — одна реальная траектория. Интервалы даны по 10 000 повторов.","",
        "[План](PROTOCOL_RU.md) · [Нативное дополнение](NATIVE_PROTOCOL_RU.md) · [Подробные числа](results.json) · [Перемешанные транзакции](durability-paired-summary.json) · [Воспроизведение](REPRODUCE_RU.md)"]
    # Published timing and byte values in narrative paragraphs follow the active results.
    facts=read(D/"native-build.json")
    fresh=v["fresh_edits"];nc=v["native_counters"]["random1"]
    sparse=v["branches"]["2048/random1"];dur=v["durable"];storage=build["storage"]
    digits=lambda x:f"{int(x):,}".replace(","," ")
    fixed=[
        ("168 случаях", str(sparse["repair_path"]["certified"])+" случаях"),
        ("7 490 индексных строк",digits(nc["repair"]["sql_rows"])+" индексных строк"),
        ("90 823,",digits(nc["rebuild"]["sql_rows"])+","),
        ("8 880.",digits(nc["cost_certificate"]["sql_rows"])+"."),
        ("125 138 инструкций",digits(nc["repair"]["vm"])+" инструкций"),
        ("101 519,",digits(nc["cost_certificate"]["vm"])+","),("922 965.",digits(nc["rebuild"]["vm"])+"."),
        ("−0,90 мкс",fmt(v["native"]["random8/rebuild"]["paired_delta_us"])+" мкс"),
        ("271,25 и 517,25 мкс",fmt(fresh["reopen"]["candidate_us"])+" и "+fmt(fresh["reopen"]["baseline_us"])+" мкс"),
        ("156,85 и 360,10 мкс",fmt(fresh["warm"]["candidate_us"])+" и "+fmt(fresh["warm"]["baseline_us"])+" мкс"),
        ("3 817 472 байта",digits(storage["blocks"]["bytes"])+" байта"),
        ("1 806 336.",digits(storage["sqlite_autoindex_blocks_1"]["bytes"])+"."),
        ("69,4 мс",fmt(build["build_ns"]["create_covering_index"]/1e6,1)+" мс"),
        ("3 919 872 байта",digits(storage["idx_priority"]["bytes"])+" байта"),
        ("2 433 024 байта",digits(storage["answers"]["bytes"])+" байта"),
        ("461 мс",fmt(build["build_ns"]["build_verify_and_materialize_answers"]/1e6,0)+" мс"),
        ("561 152 байта",digits(facts["binary_cache_2048_bytes"][0])+" байта"),
        ("2 760 432 до 2 785 152 байт",digits(min(w["wal"].values()))+" до "+digits(max(w["wal"].values()))+" байт"),
        ("791 072 байта",digits(dur["raw"]["wal_bytes"])+" байта"),("2 529 712 байт",digits(dur["covered"]["wal_bytes"])+" байт")]
    archive="\n".join(lines)+"\n"
    for before,after in fixed:
        assert before in archive
        archive=archive.replace(before,after)
    (D/"REPORT_RU.md").write_text(archive,encoding="utf8")
    manifest=D/"MANIFEST_SHA256.json";files={p.name:sha(p) for p in sorted(D.iterdir()) if p.is_file() and p!=manifest}
    save(manifest,{"files":files,"n":len(files),"bytes":sum((D/p).stat().st_size for p in files)})
    print(len(files),"files",sha(manifest))
if __name__=="__main__":main()

